/**
 * Expo config plugin — iOS scene lifecycle (iOS 27+).
 *
 * app.json declares UIApplicationSceneManifest → UISceneDelegateClassName "SceneDelegate".
 * ios/ is generated by `expo prebuild` / EAS and not versioned, so the matching Swift code
 * must be injected at prebuild time; otherwise Info.plist names a class that does not exist.
 *
 * Adds to the generated AppDelegate.swift:
 *  1. application(_:configurationForConnecting:options:) inside AppDelegate
 *  2. a SceneDelegate class that attaches the window created by AppDelegate to the scene
 *
 * Idempotent: running prebuild again does not duplicate the code.
 */
const { withAppDelegate } = require('expo/config-plugins');

const SCENE_CONFIGURATION_METHOD = `
  // Scene lifecycle support for iOS 27+ (injected by plugins/withSceneDelegate.js)
  public func application(
    _ application: UIApplication,
    configurationForConnecting connectingSceneSession: UISceneSession,
    options: UIScene.ConnectionOptions
  ) -> UISceneConfiguration {
    let sceneConfig = UISceneConfiguration(name: "Default Configuration", sessionRole: connectingSceneSession.role)
    sceneConfig.delegateClass = SceneDelegate.self
    return sceneConfig
  }
`;

const SCENE_DELEGATE_CLASS = `
// Injected by plugins/withSceneDelegate.js — must match UISceneDelegateClassName in app.json
@objc(SceneDelegate)
public class SceneDelegate: UIResponder, UIWindowSceneDelegate {
  public var window: UIWindow?

  public func scene(_ scene: UIScene, willConnectTo session: UISceneSession, options connectionOptions: UIScene.ConnectionOptions) {
    guard let windowScene = scene as? UIWindowScene else { return }

    if let appDelegate = UIApplication.shared.delegate as? AppDelegate, let appWindow = appDelegate.window {
      appWindow.windowScene = windowScene
      appWindow.makeKeyAndVisible()
      self.window = appWindow
    }
  }
}
`;

function addSceneDelegate(contents) {
  if (contents.includes('class SceneDelegate')) return contents;

  // The Expo template ends AppDelegate right before `class ReactNativeDelegate`
  const nextClass = contents.indexOf('\nclass ReactNativeDelegate');
  if (nextClass === -1) {
    throw new Error('[withSceneDelegate] Unexpected AppDelegate.swift template: `class ReactNativeDelegate` not found.');
  }
  const appDelegateEnd = contents.lastIndexOf('}', nextClass);
  if (appDelegateEnd === -1) {
    throw new Error('[withSceneDelegate] Unexpected AppDelegate.swift template: end of AppDelegate not found.');
  }

  return (
    contents.slice(0, appDelegateEnd) +
    SCENE_CONFIGURATION_METHOD +
    '}\n' +
    SCENE_DELEGATE_CLASS +
    contents.slice(nextClass)
  );
}

const withSceneDelegate = (config) =>
  withAppDelegate(config, (cfg) => {
    if (cfg.modResults.language !== 'swift') {
      throw new Error(`[withSceneDelegate] Expected a Swift AppDelegate, got ${cfg.modResults.language}.`);
    }
    cfg.modResults.contents = addSceneDelegate(cfg.modResults.contents);
    return cfg;
  });

module.exports = withSceneDelegate;
module.exports.addSceneDelegate = addSceneDelegate;
